186	
187	    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, number, settled_due, opened_by, stated, stated_due";
188	
189	    private static final RowMapper<Claim> ROW = (rs, n) -> new Claim(rs.getLong("id"),
190	            rs.getString("sheet_id"), rs.getLong("person_id"),
191	            rs.getBigDecimal("amount").setScale(2).toPlainString(),
192	            rs.getObject("claim_date", LocalDate.class).toString(), rs.getString("note"),
193	            rs.getString("status"), rs.getObject("number", Long.class),
194	            rs.getBigDecimal("settled_due") == null ? null
195	                    : rs.getBigDecimal("settled_due").setScale(2).toPlainString(),
196	            rs.getString("opened_by"), rs.getBoolean("stated"),
197	            rs.getBigDecimal("stated_due") == null ? null
198	                    : rs.getBigDecimal("stated_due").setScale(2).toPlainString());
199	
200	    private final JdbcTemplate jdbc;
201	
202	    public ClaimRepository(JdbcTemplate jdbc) {
203	        this.jdbc = jdbc;
204	    }
205	
206	    /** The sheet's claims, newest first. */
207	    public List<Claim> list(String sheetId) {
208	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY id DESC",
209	                ROW, sheetId);
210	    }
211	
212	    public Claim find(String sheetId, long id) {
213	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?",
214	                ROW, sheetId, id).stream().findFirst().orElse(null);
215	    }
216	
217	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
218	            String user) {
219	        GeneratedKeyHolder key = new GeneratedKeyHolder();
220	        jdbc.update(con -> {
221	            PreparedStatement ps = con.prepareStatement(
222	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, created_by) "
223	                            + "VALUES (?, ?, ?, ?, ?, ?)",
224	                    new String[] { "id" });
225	            ps.setString(1, sheetId);
226	            ps.setLong(2, personId);
227	            ps.setBigDecimal(3, amount);
228	            ps.setObject(4, date);
229	            ps.setString(5, note);
230	            ps.setString(6, user);
231	            return ps;
232	        }, key);
233	        return new Claim(key.getKey().longValue(), sheetId, personId, amount.toPlainString(),
234	                date.toString(), note, ClaimStatus.DRAFT.name(), null, null, null);
235	    }
236	
237	    public void update(Claim claim) {
238	        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, settled_due = ?, opened_by = ? WHERE sheet_id = ? AND id = ?",
239	                new BigDecimal(claim.getAmount()), LocalDate.parse(claim.getDate()), claim.getNote(),
240	                claim.getStatus(), claim.getNumber(),
241	                claim.getSettledDue() == null ? null : new BigDecimal(claim.getSettledDue()),
242	                claim.getOpenedBy(),
243	                claim.getSheetId(), claim.getId());
244	    }
245	
246	    /** The person's claims, newest first. */
247	    public List<Claim> listOf(String sheetId, long personId) {
248	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC",
249	                ROW, sheetId, personId);
250	    }
251	
252	    /** Save a claim's binding by its person's last statement. */
253	    public void updateBinding(Claim claim) {
254	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
255	                claim.isStated(), claim.getStatedDue() == null ? null : new BigDecimal(claim.getStatedDue()),
256	                claim.getSheetId(), claim.getId());
