284	package net.officefloor.hq.app.claim;
285	
286	/** A claim's status. It starts DRAFT; DRAFT opens to OPEN, OPEN settles to SETTLED, and DRAFT or
287	 *  OPEN voids to VOID. SETTLED and VOID are final. */
288	public enum ClaimStatus {
289	    DRAFT, OPEN, SETTLED, VOID;
290	
291	    /** The status after moving to {@code to}; refused when this status does not allow it. */
292	    public ClaimStatus moveTo(ClaimStatus to) throws ClaimStatusException {
293	        boolean allowed = switch (to) {
294	            case OPEN -> this == DRAFT;
295	            case SETTLED -> this == OPEN;
296	            case VOID -> this == DRAFT || this == OPEN;
297	            case DRAFT -> false;
298	        };
299	        if (!allowed) {
300	            throw new ClaimStatusException("A " + this + " claim cannot become " + to);
301	        }
302	        return to;
303	    }
304	
305	    /** The audit event recorded when a claim moves to this status. */
306	    public String event() {
307	        return switch (this) {
308	            case OPEN -> "CLAIM_OPENED";
309	            case SETTLED -> "CLAIM_SETTLED";
310	            case VOID -> "CLAIM_VOIDED";
311	            case DRAFT -> "CLAIM_DRAFTED";
312	        };
313	    }
314	}
