316	package net.officefloor.hq.app.claim;
317	
318	import java.math.BigDecimal;
319	import java.math.RoundingMode;
320	import java.time.LocalDate;
321	import java.time.temporal.ChronoUnit;
322	
323	/** A claim's due figure. */
324	public final class Dues {
325	    private Dues() {
326	    }
327	
328	    /** What a late charge goes by: the sheet's late percent, its terms (days) and its today. */
329	    public record Late(String pct, int terms, LocalDate today) {
330	    }
331	
332	    /** An amount times a percent, divided by 100, rounded half to even to two decimals, and at least
333	     *  the sheet's floor. */
334	    public static String of(String amount, String pct, String floor) {
335	        return new BigDecimal(amount).multiply(new BigDecimal(pct))
336	                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN)
337	                .max(new BigDecimal(floor).setScale(2)).toPlainString();
338	    }
339	
340	    /** The late charge on a claim's figure: the late percent of it for every full 30 days its OPEN
341	     *  claim is past its due-by (its date plus the terms) on the sheet's today, rounded half to even
342	     *  to two decimals; none (0.00) when it is not overdue. */
343	    public static BigDecimal charge(Claim claim, String figure, Late late) {
344	        if (figure == null || !ClaimStatus.OPEN.name().equals(claim.getStatus())) return BigDecimal.ZERO.setScale(2);
345	        LocalDate dueBy = LocalDate.parse(claim.getDate()).plusDays(late.terms());
346	        long periods = Math.max(0, ChronoUnit.DAYS.between(dueBy, late.today())) / 30;
347	        return new BigDecimal(figure).multiply(new BigDecimal(late.pct()))
348	                .multiply(BigDecimal.valueOf(periods))
349	                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN);
350	    }
351	
352	    /** The due a claim shows: the one fixed when settled, else its figure (bound by a statement, else
353	     *  {@code live}; null: none) with its late charge added on top. */
354	    public static String shown(Claim claim, String live, Late late) {
355	        if (claim.getSettledDue() != null) return claim.getSettledDue();
356	        String figure = claim.due(live);
357	        return figure == null ? null : new BigDecimal(figure).add(charge(claim, figure, late)).toPlainString();
358	    }
359	}
