575	/** Settles a claim, fixing its due: its amount at its person's grade's rate in force on its date, rounded half to even to
576	 *  two decimals and at least the sheet's floor (a claim bound by a statement: the figure it was bound to). With no rate the due is not
577	 *  fixed and stays live. Its late charge on the sheet's today is added and fixed with it. Refused for the user who opened it (four eyes), and for a clerk when the due
578	 *  is above the sheet's clerk limit (a due that is n/a is within any limit; a steward settles anything). */
579	public class SettleClaim {
580	    public void move(@RequestParam(name = "by", required = false) String by, @Val Claim claim,
581	            PersonRepository people, RateRepository rates, PeriodRepository periods,
582	            RoleRepository roles, SettingRepository settings, SheetRepository sheets)
583	            throws ClaimStatusException, ClaimLimitException, PeriodClosedException {
584	        periods.requireOpen(claim.getSheetId(), claim.getDate());
585	        ClaimStatus settled = ClaimStatus.valueOf(claim.getStatus()).moveTo(ClaimStatus.SETTLED);
586	        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(by == null ? "" : by)) {
587	            throw new ClaimStatusException("The user who opened a claim cannot settle it");
588	        }
589	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
590	        Rate rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()),
591	                LocalDate.parse(claim.getDate()));
592	        // A claim bound by a statement settles at the figure it was bound to.
593	        // Its late charge on the sheet's today is frozen in.
594	        String due = Dues.shown(claim,
595	                rate == null ? null : Dues.of(claim.getAmount(), rate.pct(), settings.floor(claim.getSheetId())),
596	                settings.late(claim.getSheetId(), sheets.today(claim.getSheetId())));
597	        if (due != null && Role.CLERK.equals(roles.roleOf(claim.getSheetId(), by == null ? "" : by))) {
598	            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
599	            if (limit != null && new BigDecimal(due).compareTo(limit) > 0) {
600	                throw new ClaimLimitException("A clerk cannot settle a claim whose due is above the clerk limit");
601	            }
602	        }
603	        claim.setStatus(settled.name());
604	        claim.setSettledDue(due);
